const NON_MAIN = new Set(['memory', 'quote', 'dream', 'hypothetical', 'hearsay', 'plan', 'unknown']);
const OWNERSHIP = new Set(['owned', 'gifted', 'purchased', 'borrowed', 'temporary', 'custody', 'stored', 'unknown']);
const CONTAINERS = new Set(['carried', 'inventory', 'sleeve', 'storage_space', 'room', 'other']);
const RELATION_DIMENSIONS = new Set(['formal', 'trust', 'hostility', 'affection', 'alliance', 'authority', 'other']);
const ASSET_REMOVE = new Set(['discard', 'lose', 'destroy', 'clear', 'return']);
const ASSET_DECREASE = new Set(['consume', 'subtract']);

function clean(value) { const result = String(value ?? '').trim(); return result || null; }
function source(event) { const value = event.sourceOrder; return value && Number.isInteger(value.messageIndex) && Number.isInteger(value.evidenceOrder) ? value : { messageIndex: Number(event.sourceMessageIndex) || 0, evidenceOrder: 0 }; }
function compareEvents(left, right) { const a = source(left); const b = source(right); return a.messageIndex - b.messageIndex || a.evidenceOrder - b.evidenceOrder; }
function isCommittedMain(event) { return event && event.deletedAt === null && !event.invalid && !['pending', 'rejected', 'reject', 'deferred'].includes(event.disposition) && !NON_MAIN.has(event.timelineContext); }
function quantity(value) { const raw = value?.quantity; if (raw && typeof raw === 'object') return { exact: Number.isFinite(raw.exact) && raw.exact >= 0 ? raw.exact : null, unit: clean(raw.unit), text: clean(raw.text), isExact: Number.isFinite(raw.exact) && raw.exact >= 0 }; const exact = Number(value?.quantity ?? value?.amount); return { exact: Number.isFinite(exact) && exact >= 0 ? exact : null, unit: clean(value?.unit), text: null, isExact: Number.isFinite(exact) && exact >= 0 }; }
function container(value) { const raw = value?.container; const type = clean(raw?.type ?? raw); return { type: CONTAINERS.has(type) ? type : 'carried', display: clean(raw?.display), placeId: clean(raw?.placeId) }; }
function itemName(value) { return clean(value?.canonicalName ?? value?.name ?? value?.item); }
function ownership(value) { return OWNERSHIP.has(value?.ownership) ? value.ownership : 'unknown'; }
function assetId(owner, name, own, box, unit) { return [owner, name, own, box.type, box.display ?? '', box.placeId ?? '', unit ?? ''].join('|'); }
function sameAsset(asset, owner, name) { return asset.current && asset.ownerEntityId === owner && asset.canonicalName === name; }
function allUsed(value) { return value?.all === true || /全部|全數|用完|耗盡/.test(clean(value?.quantity?.text ?? value?.quantityText ?? value?.description) ?? ''); }
function currentAssets(state, owner, name) { return state.assets.filter((asset) => sameAsset(asset, owner, name)); }
function closeAssets(state, owner, name, event) { for (const asset of currentAssets(state, owner, name)) { asset.current = false; asset.sourceEventId = event.eventId; asset.updatedStoryOrder = source(event); } }
function putAsset(state, owner, value, event, amount = quantity(value), prior = null) { const name = itemName(value); if (!owner || !name) return null; const box = container(value); const own = ownership(value); const id = assetId(owner, name, own, box, amount.unit); const index = state.assets.findIndex((asset) => asset.assetId === id); const old = index >= 0 ? state.assets[index] : null; const asset = { assetId: id, canonicalName: name, displayName: clean(value.displayName ?? value.name) ?? name, ownerEntityId: owner, ownership: own, container: box, quantity: amount, current: true, sourceEventId: event.eventId, updatedStoryOrder: source(event) }; if (prior && amount.exact === null) asset.quantity = { ...prior.quantity }; if (old) state.assets[index] = asset; else state.assets.push(asset); return asset; }
function applyAsset(state, event) { const value = event.value ?? {}; const owner = clean(event.subjectEntityId ?? value.ownerEntityId); const name = itemName(value); if (!owner || !name) return; const operation = event.operation;
  if (ASSET_REMOVE.has(operation)) { const previous = currentAssets(state, owner, name)[0]; closeAssets(state, owner, name, event); if (operation === 'return' && clean(value.toOwnerEntityId ?? value.targetOwnerEntityId)) { if (previous) putAsset(state, clean(value.toOwnerEntityId ?? value.targetOwnerEntityId), { ...value, ownership: previous.ownership, container: previous.container, quantity: previous.quantity }, event, previous.quantity, previous); } return; }
  if (operation === 'move') { const previous = currentAssets(state, owner, name)[0]; if (!previous) return; closeAssets(state, owner, name, event); putAsset(state, owner, { ...value, ownership: previous.ownership, quantity: value.quantity ?? previous.quantity }, event, quantity(value).exact === null ? previous.quantity : quantity(value), previous); return; }
  if (operation === 'transfer') { const destination = clean(value.toOwnerEntityId ?? value.targetOwnerEntityId ?? value.recipientEntityId); const previous = currentAssets(state, owner, name)[0]; if (!previous || !destination) return; closeAssets(state, owner, name, event); putAsset(state, destination, { ...value, ownership: value.ownership ?? previous.ownership, container: value.container ?? previous.container, quantity: value.quantity ?? previous.quantity }, event, quantity(value).exact === null ? previous.quantity : quantity(value), previous); return; }
  const requested = quantity(value); const previous = currentAssets(state, owner, name).find((asset) => asset.assetId === assetId(owner, name, ownership(value), container(value), requested.unit)) ?? currentAssets(state, owner, name)[0] ?? null;
  if (ASSET_DECREASE.has(operation)) { if (!previous || requested.exact === null || previous.quantity.exact === null || requested.exact > previous.quantity.exact) return; const next = previous.quantity.exact - requested.exact; previous.quantity = { ...previous.quantity, exact: next, isExact: true }; previous.current = next > 0; previous.sourceEventId = event.eventId; previous.updatedStoryOrder = source(event); return; }
  const amount = operation === 'set' ? requested : !previous || requested.exact === null || previous.quantity.exact === null ? requested : { ...requested, exact: previous.quantity.exact + requested.exact, isExact: true }; putAsset(state, owner, value, event, amount, previous);
}
function applyCurrency(state, event) { const value = event.value ?? {}; const owner = clean(event.subjectEntityId ?? value.ownerEntityId); const name = clean(value.name ?? value.currency); if (!owner || !name) return; const amount = Number(value.amount ?? value.quantity?.exact ?? value.quantity); if (!Number.isFinite(amount) || amount < 0) return; const box = container(value); const key = [owner, name, clean(value.unit) ?? '', clean(value.tier ?? value.grade) ?? '', box.type, box.display ?? '', box.placeId ?? ''].join('|'); const index = state.currencies.findIndex((entry) => entry.currencyId === key); const old = index < 0 ? null : state.currencies[index]; const next = event.operation === 'set' ? amount : old?.amount == null ? amount : old.amount + (event.operation === 'subtract' ? -amount : amount); if (next < 0) return; const entry = { currencyId: key, name, ownerEntityId: owner, amount: next, unit: clean(value.unit), tier: clean(value.tier ?? value.grade), container: box, current: next > 0, sourceEventId: event.eventId, updatedStoryOrder: source(event) }; if (index < 0) state.currencies.push(entry); else state.currencies[index] = entry; }
function entity(state, id, value = {}) { return state.entities[id] ?? { entityId: id, canonicalName: clean(value.canonicalName ?? value.name), aliases: [], currentLocation: null, durableStatuses: [], durableStatusHistory: [], transientStates: {} }; }
function statusKey(id, value) { return `${id}:${clean(value.statusKey ?? value.status ?? value.dimension) ?? 'state'}`; }
function applyPerson(state, event) { const value = event.value ?? {}; const id = clean(event.subjectEntityId ?? value.entityId); if (!id) return; const entry = entity(state, id, value); const alias = clean(value.name ?? value.canonicalName); if (alias && !entry.aliases.includes(alias)) entry.aliases.push(alias); if (event.kind === 'place') { entry.currentLocation = clean(value.name ?? value.place); state.entities[id] = entry; return; } const label = clean(value.status); if (!label) { state.entities[id] = entry; return; } const key = statusKey(id, value); if (value.stateType === 'transient' || value.transient === true) { const dimension = clean(value.dimension) ?? key; if (event.operation === 'clear' || event.operation === 'resolve') delete entry.transientStates[dimension]; else entry.transientStates[dimension] = { statusKey: key, label, dimension, sourceEventId: event.eventId, updatedStoryOrder: source(event) }; } else { const index = entry.durableStatuses.findIndex((status) => status.statusKey === key); if (event.operation === 'clear' || event.operation === 'resolve') { const old = index >= 0 ? entry.durableStatuses[index] : null; if (index >= 0) entry.durableStatuses.splice(index, 1); entry.durableStatusHistory.push({ statusKey: key, label, state: 'resolved', startedByEventId: old?.startedByEventId ?? null, resolvedByEventId: event.eventId, updatedStoryOrder: source(event) }); } else { const next = { statusKey: key, label, state: 'active', startedByEventId: event.eventId, resolvedByEventId: null, updatedStoryOrder: source(event) }; if (index < 0) entry.durableStatuses.push(next); else entry.durableStatuses[index] = next; } } state.entities[id] = entry; }
function applyRelationship(state, event) { const value = event.value ?? {}; const from = clean(event.subjectEntityId ?? value.fromEntityId); const to = clean(value.targetEntityId ?? value.toEntityId); const dimension = clean(value.dimension) ?? 'other'; if (!from || !to || !RELATION_DIMENSIONS.has(dimension) || (!clean(value.formalStatus ?? value.relationship ?? value.label) && !clean(value.trend))) return; if (/[0-9]/.test(String(value.affection ?? value.trust ?? value.value ?? ''))) return; const key = `${from}|${to}|${dimension}`; if (event.operation === 'clear') delete state.relationships[key]; else state.relationships[key] = { relationshipId: key, fromEntityId: from, toEntityId: to, dimension, formalStatus: clean(value.formalStatus ?? value.relationship ?? value.label), trend: clean(value.trend) ?? 'unknown', sourceEventId: event.eventId, updatedStoryOrder: source(event) }; }

export function createCurrentSnapshot() { return { schemaVersion: 1, playerEntityId: 'entity:player', currentTime: null, currentPlace: null, assets: [], currencies: [], entities: {}, relationships: {}, sourceEventIds: [], rebuiltAt: null }; }
export function rebuildCurrentSnapshot(events = [], rebuiltAt = null) { const state = createCurrentSnapshot(); const accepted = events.filter(isCommittedMain); for (const event of [...accepted].sort(compareEvents)) { const value = event.value ?? {}; if (event.kind === 'story_time' && clean(value.time ?? value.canonicalDisplay)) state.currentTime = clean(value.time ?? value.canonicalDisplay); else if (event.kind === 'place') { const id = clean(event.subjectEntityId ?? value.subjectEntityId); if (!id || id === state.playerEntityId) state.currentPlace = clean(value.name ?? value.place); else applyPerson(state, event); } else if (event.kind === 'inventory') applyAsset(state, event); else if (event.kind === 'currency') applyCurrency(state, event); else if (event.kind === 'person' || event.kind === 'person_state') applyPerson(state, event); else if (event.kind === 'relationship') applyRelationship(state, event); } state.assets.sort((a,b) => a.assetId.localeCompare(b.assetId)); state.currencies.sort((a,b) => a.currencyId.localeCompare(b.currencyId)); state.sourceEventIds = accepted.map((event) => event.eventId); state.rebuiltAt = rebuiltAt; return state; }